export type EasypayPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function easypayProgram() {
  return <T extends EasypayPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { easypay: EasypayPlugin }> => {
    return extendClient(client, {
      easypay: <EasypayPlugin>{
        accounts: {
          exchange: addSelfFetchFunctions(client, getExchangeCodec()),
          offer: addSelfFetchFunctions(client, getOfferCodec()),
          pool: addSelfFetchFunctions(client, getPoolCodec()),
          split: addSelfFetchFunctions(client, getSplitCodec()),
        },
        instructions: {
          accept: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcceptInstructionAsync(input),
            ),
          cancelOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelOfferInstruction(input),
            ),
          claim: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimInstructionAsync(input),
            ),
          createPool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreatePoolInstructionAsync(input),
            ),
          deposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositInstructionAsync(input),
            ),
          endContract: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEndContractInstructionAsync(input),
            ),
          initExchange: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitExchangeInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          propose: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProposeInstructionAsync(input),
            ),
          setSplit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetSplitInstructionAsync(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input),
            ),
        },
        pdas: {
          pool: findPoolPda,
          offer: findOfferPda,
          split: findSplitPda,
          exchange: findExchangePda,
          btcMint: findBtcMintPda,
          ethMint: findEthMintPda,
        },
        identifyAccount: identifyEasypayAccount,
        identifyInstruction: identifyEasypayInstruction,
        parseInstruction: parseEasypayInstruction,
      },
    });
  };
}

